        {
          test_flags = transitional ? TR46_TRANSITIONAL_CHECK : TR46_NONTRANSITIONAL_CHECK;

          if (!(flags & IDN2_USE_STD3_ASCII_RULES))
            test_flags |= TEST_ALLOW_STD3_DISALLOWED;

          if ((rc =
               _idn2_label_test (test_flags, s, e - s)))
            err = rc;
